{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO/JCO relocation assistance amounts for 2026-27","requirement":"A landlord who displaces a tenant from an RSO or JCO unit must pay relocation assistance per unit: $11,000 or $14,400 for an eligible tenant, and $23,150 or $27,400 for a qualified tenant.","key_value":"$11,000–$27,400 per unit (2026-07-01 to 2027-06-30)","coverage_conditions":"Tenants displaced from RSO or JCO rental units; amounts depend on eligible or qualified tenant status and on length of tenancy (less than three years, or three or more years or low income).","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"RSO and JCO covered rental units in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":"2026-07-01","citation":"L.A. Relocation Assistance Bulletin, Chart A","quoted_span":"CHART A: RSO or JCO Amounts
