{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RPO standardized relocation payments for new development displacement","requirement":"Where lower income tenants are displaced by new development, the owner must pay standardized relocation of $115,480 for extremely low income, $96,750 for very low income or $87,450 for low income households per unit.","key_value":"$115,480 / $96,750 / $87,450 (extremely low / very low / low income)","coverage_conditions":"Only households with Extremely Low, Very Low or Low income who are displaced by new development.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Tenants displaced by new development in the City of Los Angeles"},"exemptions":"Above low income households displaced by new development are not paid these standardized amounts; the RSO or JCO amounts in Chart A apply to them.","penalty":null,"effective_date":"2026-07-01","citation":"L.A. Relocation Assistance Bulletin, Chart B","quoted_span":"CHART B: Resident Protections Ordinance Standardized Payments
